(window.webpackJsonpGUI=window.webpackJsonpGUI||[]).push([[174],{1513:function(t,e,p){"use strict";p.r(e),e.default={code:"M1-07",title:"排序法：交換與選擇排序",tier:"t1",unlockCode:"M1-07-SortBasics",tasks:[{id:"SORT01-001",code:"M1-07-SORT01-001",title:"（兩數交換成升冪",description:"給定兩個整數，請將它們由小到大輸出。",examples:[{input:"8 3",output:"3 8",explanation:"3 比 8 小，所以輸出 3 8。"}],testCases:[{input:"8 3",expectedOutput:"3 8",score:0},{input:"2 9",expectedOutput:"2 9",score:0},{input:"5 5",expectedOutput:"5 5",score:0},{input:"-1 -7",expectedOutput:"-7 -1",score:0}],difficulty:"L1",difficultyLabel:"L1｜基礎",sb3Path:"m0/M1-07-SortBasics/SORT01-001.sb3"},{id:"seclect-001",code:"M1-07-seclect-001",title:"SWAP交換函數",description:"在學習排序之前，小安先練習一個重要的小任務。\n桌上有兩張數字卡片，依序放在第 1 個位置與第 2 個位置。\n小安希望讓「數字小的卡片在前面，數字大的卡片在後面」。\n如果前面的數字比較大，就需要把兩張卡片的位置交換；\n如果順序本來就正確，則不需要交換。\n請你寫一個程式，判斷是否需要交換，並輸出交換後的結果。\n（提示：交換時需要使用暫存變數）",examples:[{input:"8 3",output:"3 8",explanation:"前面的數字 8 比後面的 3 大，\n需要交換兩個數字的位置。"},{input:"4 9",output:"4 9",explanation:"前面的數字較小，順序正確，\n不需要交換。"}],testCases:[{input:"8 3",expectedOutput:"3 8",score:10},{input:"4 9",expectedOutput:"4 9",score:10},{input:"6 6",expectedOutput:"6 6",score:10},{input:"0 5",expectedOutput:"0 5",score:10},{input:"9 0",expectedOutput:"0 9",score:10}],difficulty:"L1",difficultyLabel:"L1｜基礎",sb3Path:"m0/M1-07-SortBasics/seclect-001.sb3"},{id:"SORT01-002",code:"M1-07-SORT01-002",title:"三數升冪排序",description:"給定三個整數，請將它們由小到大輸出。這題可用多次相鄰比較與交換完成。",examples:[{input:"9 2 5",output:"2 5 9",explanation:"三個數由小到大為 2、5、9。"}],testCases:[{input:"9 2 5",expectedOutput:"2 5 9",score:0},{input:"1 2 3",expectedOutput:"1 2 3",score:0},{input:"3 3 1",expectedOutput:"1 3 3",score:0},{input:"-1 8 0",expectedOutput:"-1 0 8",score:0}],difficulty:"L2",difficultyLabel:"L2｜進階",sb3Path:"m0/M1-07-SortBasics/SORT01-002.sb3"},{id:"SORT01-003",code:"M1-07-SORT01-003",title:"相鄰交換一次",description:"給定 N 個整數，請從左到右檢查每一組相鄰數字。如果左邊數字大於右邊數字，就交換兩者。整個清單只掃描一次。",examples:[{input:"5\n5 1 4 2 3",output:"1 4 2 3 5",explanation:"泡泡排序掃描一輪後，最大值 5 會移到最右邊。"}],testCases:[{input:"5\n5 1 4 2 3",expectedOutput:"1 4 2 3 5",score:0},{input:"4\n1 2 3 4",expectedOutput:"1 2 3 4",score:0},{input:"4\n4 3 2 1",expectedOutput:"3 2 1 4",score:0},{input:"6\n2 9 1 8 3 7",expectedOutput:"2 1 8 3 7 9",score:0}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-07-SortBasics/SORT01-003.sb3"},{id:"SORT01-004",code:"M1-07-SORT01-004",title:"泡泡排序升冪",description:"給定 N 個整數，請使用排序概念將它們由小到大輸出。",examples:[{input:"5\n5 1 4 2 3",output:"1 2 3 4 5",explanation:"排序後由小到大為 1 2 3 4 5。"}],testCases:[{input:"5\n5 1 4 2 3",expectedOutput:"1 2 3 4 5",score:0},{input:"4\n1 2 3 4",expectedOutput:"1 2 3 4",score:0},{input:"4\n4 3 2 1",expectedOutput:"1 2 3 4",score:0},{input:"6\n-1 5 0 -3 2 2",expectedOutput:"-3 -1 0 2 2 5",score:0}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-07-SortBasics/SORT01-004.sb3"},{id:"SORT01-005",code:"M1-07-SORT01-005",title:"泡泡排序降冪",description:"給定 N 個整數，請將它們由大到小輸出。",examples:[{input:"5\n5 1 4 2 3",output:"5 4 3 2 1",explanation:"排序後由大到小為 5 4 3 2 1。"}],testCases:[{input:"5\n5 1 4 2 3",expectedOutput:"5 4 3 2 1",score:0},{input:"4\n1 2 3 4",expectedOutput:"4 3 2 1",score:0},{input:"4\n4 3 2 1",expectedOutput:"4 3 2 1",score:0},{input:"6\n-1 5 0 -3 2 2",expectedOutput:"5 2 2 0 -1 -3",score:0}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-07-SortBasics/SORT01-005.sb3"},{id:"SORT01-006",code:"M1-07-SORT01-006",title:"排序後的中間值",description:"給定奇數個整數，請將它們由小到大排序後，輸出中間位置的數字。位置從 1 開始計算。",examples:[{input:"5\n9 1 5 3 7",output:"5",explanation:"排序後為 1 3 5 7 9，中間值是 5。"}],testCases:[{input:"5\n9 1 5 3 7",expectedOutput:"5",score:0},{input:"3\n10 2 8",expectedOutput:"8",score:0},{input:"7\n4 4 1 9 2 8 6",expectedOutput:"4",score:0},{input:"1\n99",expectedOutput:"99",score:0}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-07-SortBasics/SORT01-006.sb3"},{id:"SORT01-007",code:"M1-07-SORT01-007",title:"排序後第K小",description:"給定 N 個整數與 K，請將數字由小到大排序後，輸出第 K 小的數字。位置從 1 開始計算。",examples:[{input:"6\n8 3 9 1 5 7\n2",output:"3",explanation:"排序後為 1 3 5 7 8 9，第 2 小是 3。"}],testCases:[{input:"6\n8 3 9 1 5 7\n2",expectedOutput:"3",score:0},{input:"5\n5 4 3 2 1\n5",expectedOutput:"5",score:0},{input:"5\n5 4 3 2 1\n1",expectedOutput:"1",score:0},{input:"4\n10 10 8 9\n3",expectedOutput:"10",score:0}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-07-SortBasics/SORT01-007.sb3"},{id:"SORT01-008",code:"M1-07-SORT01-008",title:"排序後去除最高最低）＋",description:"給定 N 個整數，請排序後去除一個最低值與一個最高值，再計算剩下數字的總和。保證 N 大於或等於 3。",examples:[{input:"5\n80 90 70 100 60",output:"240",explanation:"排序後為 60 70 80 90 100，去除 60 和 100，剩下總和為 240。"}],testCases:[{input:"5\n80 90 70 100 60",expectedOutput:"240",score:0},{input:"3\n10 20 30",expectedOutput:"20",score:0},{input:"6\n5 5 5 5 5 5",expectedOutput:"20",score:0},{input:"7\n9 1 8 2 7 3 6",expectedOutput:"26",score:0}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-07-SortBasics/SORT01-008.sb3"},{id:"seclect-004",code:"M1-07-seclect-004",title:"選擇排序第一回合",description:"小安正在學習「選擇排序法」，老師請他先完成第一回合的任務。\n桌上有一排固定 5 個的數字，依序放在第 1 到第 5 個位置中。\n請你找出這 5 個數字中最小的數字，並把它與第 1 個位置的數字交換。\n注意事項：\n1. 只進行「第一回合」，不需要完成整個排序。\n2. 若最小值有多個，請選擇最前面出現的那一個。\n3. 交換完成後，其餘位置的數字順序保持不變",examples:[{input:"5\n8 3 5 1 6",output:"1 3 5 8 6",explanation:"最小值為 1（在第4個位置），\n與第1個位置的 8 交換。"},{input:"5\n2 4 6 8 10",output:"2 4 6 8 10",explanation:"最小值已在第1個位置，\n不需交換。"}],testCases:[{input:"5\n8 3 5 1 6",expectedOutput:"1 3 5 8 6",score:10},{input:"5\n2 4 6 8 10",expectedOutput:"2 4 6 8 10",score:10},{input:"5\n5 4 3 2 1",expectedOutput:"1 4 3 2 5",score:10},{input:"5\n7 2 2 9 5",expectedOutput:"2 7 2 9 5",score:10},{input:"5\n9 8 7 6 5",expectedOutput:"5 8 7 6 9",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-07-SortBasics/seclect-004.sb3"},{id:"seclect-005",code:"M1-07-seclect-005",title:"完整選擇排序",description:"小安已經學會如何在清單中找出最小值，並進行兩數交換。\n現在老師請他完成完整的選擇排序任務。\n桌上有一排固定 5 個整數，請你使用「選擇排序法」，\n將這些數字由小到大排序。\n選擇排序說明：\n1. 從尚未排序的部分中找出最小值。\n2. 將最小值與目前排序位置的數字交換。\n3. 重複上述步驟，直到整個清單排序完成。\n注意事項：\n1. 不可使用排序相關的積木或指令。\n2. 若有相同數字，排序後相對位置不限",examples:[{input:"5\n8 3 5 1 6",output:"1 3 5 6 8",explanation:"依序找出最小值並交換，\n完成由小到大的排序。"},{input:"5\n2 4 6 8 10",output:"2 4 6 8 10",explanation:"原本已經排序完成，\n結果不變。"}],testCases:[{input:"5\n8 3 5 1 6",expectedOutput:"1 3 5 6 8",score:10},{input:"5\n2 4 6 8 10",expectedOutput:"2 4 6 8 10",score:10},{input:"5\n5 4 3 2 1",expectedOutput:"1 2 3 4 5",score:10},{input:"5\n7 2 2 9 5",expectedOutput:"2 2 5 7 9",score:10},{input:"5\n9 1 8 1 7",expectedOutput:"1 1 7 8 9",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-07-SortBasics/seclect-005.sb3"},{id:"seclect-006",code:"M1-07-seclect-006",title:"排序演算法",description:"資訊課中，老師給了小華一排數字卡片，每張卡片上都有一個整數。\n小華想要把這些卡片由小到大排好，但老師規定：\n不能使用任何「排序」積木，只能使用重複、比較與變數。\n小華想到一個方法：\n每一回合從「還沒排好的卡片」中，找出最小的數字，依序放到前面。\n請你寫一個程式，依照這個想法，將輸入的數字由小到大排序後",examples:[{input:"5\n8 3 5 1 6",output:"1 3 5 6 8",explanation:"第1次找最小值為 1\n第2次在剩下的數中找最小值為 3\n依序完成排序。"},{input:"4\n7 2 2 9",output:"2 2 7 9",explanation:"排序時需正確處理重複數字。"}],testCases:[{input:"5\n8 3 5 1 6",expectedOutput:"1 3 5 6 8",score:10},{input:"4\n7 2 2 9",expectedOutput:"2 2 7 9",score:10},{input:"5\n1 2 3 4 5",expectedOutput:"1 2 3 4 5",score:10},{input:"5\n9 8 7 6 5",expectedOutput:"5 6 7 8 9",score:10},{input:"1\n4",expectedOutput:"4",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-07-SortBasics/seclect-006.sb3"}]}}}]);